import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// --- Font Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type VerticalCardsProps = Record<string, any>;

// --- Sub-Components ---

const CardContainer: React.FC<{
  children: React.ReactNode;
  delay: number;
  width: number;
  height: number;
  cardColor: string;
  rotation: number;
  zIndex: number;
  xOffset?: number;
}> = ({ children, delay, width, height, cardColor, rotation, zIndex, xOffset = 0 }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const entrance = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  const opacity = interpolate(frame - delay, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Interpolate rotation from 0 (stacked) to target rotation (fanned)
  const currentRotation = interpolate(entrance, [0, 1], [0, rotation]);

  // Interpolate horizontal separation
  const currentTranslateX = interpolate(entrance, [0, 1], [0, xOffset]);

  return (
    <div
      style={{
        width: width,
        height: height,
        backgroundColor: cardColor,
        borderRadius: 24,
        boxShadow: "0 20px 50px rgba(0,0,0,0.15), 0 5px 15px rgba(0,0,0,0.05)",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        // Apply scaling, then translation (separation), then rotation
        transform: `scale(${entrance}) translateX(${currentTranslateX}px) rotate(${currentRotation}deg)`,
        transformOrigin: "bottom center",
        opacity,
        position: "absolute", // Absolute for stacking
        overflow: "hidden",
        zIndex: zIndex,
        border: "1px solid rgba(0,0,0,0.05)",
      }}
    >
      {children}
    </div>
  );
};

const CounterCard: React.FC<{
  target: number;
  delay: number;
  color: string;
  textColor: string;
}> = ({ target, delay, color, textColor }) => {
  const frame = useCurrentFrame();
  
  // Trigger internal animation slightly after card appears
  const internalStart = delay + 10;
  
  const value = interpolate(frame - internalStart, [0, 60], [0, target], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: (t) => 1 - Math.pow(1 - t, 3), // Cubic out
  });

  return (
    <div style={{ textAlign: "center", padding: 20 }}>
      <h2 style={{ 
        margin: 0, 
        fontSize: 60, // Adjusted for narrower 9:16 card
        fontWeight: 800, 
        color: color,
        fontVariantNumeric: "tabular-nums",
        lineHeight: 1.1,
      }}>
        {Math.floor(value).toLocaleString()}
      </h2>
      <p style={{ margin: "10px 0 0 0", fontSize: 20, fontWeight: 600, color: textColor, opacity: 0.6 }}>
        Active Users
      </p>
    </div>
  );
};

const ChartCard: React.FC<{
  delay: number;
  color: string;
}> = ({ delay, color }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  
  const internalStart = delay + 15;
  const data = [0.4, 0.7, 0.5, 0.9, 0.6, 0.8, 0.3];

  return (
    <div style={{ 
      display: "flex", 
      alignItems: "flex-end", 
      justifyContent: "space-between", 
      width: "75%", 
      height: "40%", // Adjusted height relative to tall card
      gap: 8 
    }}>
      {data.map((h, i) => {
        const barSpring = spring({
          frame: frame - internalStart - (i * 3),
          fps,
          config: { damping: 15 },
        });

        return (
          <div
            key={i}
            style={{
              flex: 1,
              backgroundColor: color,
              height: `${h * 100}%`,
              borderRadius: 4,
              transformOrigin: "bottom",
              transform: `scaleY(${barSpring})`,
            }}
          />
        );
      })}
    </div>
  );
};

const TextHighlightCard: React.FC<{
  text: string;
  delay: number;
  color: string;
  textColor: string;
}> = ({ text, delay, color, textColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const internalStart = delay + 15;

  const textOpacity = interpolate(frame - internalStart, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const underlineScale = spring({
    frame: frame - internalStart - 10,
    fps,
    config: { damping: 20 },
  });

  return (
    <div style={{ position: "relative", padding: "0 30px", width: "100%", display: "flex", justifyContent: "center" }}>
      <div style={{ position: "relative", display: "inline-block" }}>
        <h3 style={{ 
          margin: 0, 
          fontSize: 32, // Adjusted for narrower 9:16 card
          fontWeight: 700, 
          color: textColor, 
          opacity: textOpacity,
          position: "relative",
          zIndex: 2,
          textAlign: "center"
        }}>
          {text}
        </h3>
        <div style={{
          position: "absolute",
          bottom: 2,
          left: 0,
          width: "100%",
          height: 12,
          backgroundColor: color,
          opacity: 0.3,
          transform: `scaleX(${underlineScale})`,
          transformOrigin: "left",
          borderRadius: 4,
          zIndex: 1,
        }} />
      </div>
    </div>
  );
};

// --- Main Component ---

const VerticalCards: React.FC<VerticalCardsProps> = ({
  backgroundColor = "#F5F5F7",
  transparentBackground = false,
  cardBackgroundColor = "#FFFFFF",
  primaryColor = "#3B82F6",
  textColor = "#1F2937",
  durationInSeconds = 8,
  counterTarget = 1000,
  headlineText = "Growth metrics",
}) => {
  useFontLoader(["Inter"]);
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate card dimensions for 9:16 aspect ratio
  // We scale the card height based on video height to fit comfortably
  const cardHeight = height * 0.65; // Cards take up 65% of screen height
  const cardWidth = cardHeight * (9 / 16); // Enforce 9:16 aspect ratio for the card itself
  
  // Separation amount for left/right cards
  // Increased to 1.1x card width to ensure cards do not overlap
  const xSeparation = cardWidth * 1.1;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        perspective: 1000, // Adds depth to the rotation
      }}
    >
      <div style={{ 
        position: "relative", 
        width: cardWidth, 
        height: cardHeight,
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-end" // Align to bottom so fanning happens from bottom-center
      }}>
        
        {/* Card 1: Counter (Left) */}
        <CardContainer 
          delay={0} 
          width={cardWidth} 
          height={cardHeight} 
          cardColor={cardBackgroundColor}
          rotation={-30} 
          zIndex={2}
          xOffset={-xSeparation} // Move left
        >
          <CounterCard 
            target={counterTarget} 
            delay={0} 
            color={primaryColor} 
            textColor={textColor}
          />
        </CardContainer>

        {/* Card 3: Text Highlight (Right) */}
        <CardContainer 
          delay={25} 
          width={cardWidth} 
          height={cardHeight} 
          cardColor={cardBackgroundColor}
          rotation={30}
          zIndex={3}
          xOffset={xSeparation} // Move right
        >
          <TextHighlightCard 
            text={headlineText} 
            delay={25} 
            color={primaryColor}
            textColor={textColor}
          />
        </CardContainer>

        {/* Card 2: Bar Chart (Center) */}
        <CardContainer 
          delay={12} 
          width={cardWidth} 
          height={cardHeight} 
          cardColor={cardBackgroundColor}
          rotation={0} 
          zIndex={1}
          xOffset={0} // Stays center
        >
          <ChartCard delay={12} color={primaryColor} />
        </CardContainer>

      </div>
    </AbsoluteFill>
  );
};

export default VerticalCards;